'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path'),{spawn}=require('child_process'),{db}=require('../db'),{DATA_DIR,APP_DIR}=require('../paths');const router=express.Router();let busy=false;
function command(bin,args){return new Promise((resolve,reject)=>{const p=spawn(bin,args,{stdio:['ignore','ignore','pipe']}),timer=setTimeout(()=>p.kill(),180000);let err='';p.stderr.on('data',b=>err=(err+b).slice(-2000));p.on('error',e=>{clearTimeout(timer);reject(e)});p.on('close',code=>{clearTimeout(timer);code===0?resolve():reject(Error('Không xuất được video: '+err.slice(-250)))})})}
router.post('/',async(req,res)=>{if(busy)return res.status(409).json({error:'Đang xuất video giữ ảnh gốc. Chờ lượt hiện tại hoàn tất.'});let temp;try{const{refTags,ratio='9:16',duration=10,cameraLock=true}=req.body;if(!Array.isArray(refTags)||!refTags.length||refTags.length>5||new Set(refTags).size!==refTags.length)throw Error('Chọn 1–5 ảnh khác nhau.');if(!['9:16','16:9','1:1'].includes(ratio)||![5,10].includes(Number(duration)))throw Error('Tỷ lệ hoặc thời lượng không hợp lệ.');const files=refTags.map(tag=>{const r=db.prepare('SELECT filepath,archived_at FROM ref_images WHERE tag=?').get(String(tag));if(!r||r.archived_at||!fs.existsSync(r.filepath))throw Error('Chọn lại ảnh đầu vào đã mất.');return r.filepath});busy=true;const ffmpeg=require(path.join(APP_DIR,'vendor/media/node_modules/ffmpeg-static')).replace(/app\.asar([/\\])/,'app.asar.unpacked$1'),id='exact_'+crypto.randomUUID().replaceAll('-','').slice(0,20),dir=path.join(DATA_DIR,'videos');fs.mkdirSync(dir,{recursive:true});temp=path.join(dir,id+'_work');fs.mkdirSync(temp);const [w,h]=ratio==='9:16'?[1080,1920]:ratio==='16:9'?[1920,1080]:[1080,1080],fps=25,total=Number(duration)*fps,base=Math.floor(total/files.length),clips=[];for(let i=0;i<files.length;i++){const frames=base+(i===files.length-1?total-base*files.length:0),out=path.join(temp,i+'.mp4');let filter=`scale=${w}:${h}:force_original_aspect_ratio=decrease,pad=${w}:${h}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1`;if(!cameraLock)filter+=`,zoompan=z='1+0.025*on/${frames}':x='iw/2-iw/zoom/2':y='ih/2-ih/zoom/2':d=1:s=${w}x${h}:fps=${fps}`;await command(ffmpeg,['-y','-loop','1','-i',files[i],'-vf',filter,'-frames:v',String(frames),'-r',String(fps),'-c:v','libx264','-preset','veryfast','-crf','18','-pix_fmt','yuv420p',out]);clips.push(out)}const list=path.join(temp,'clips.txt');fs.writeFileSync(list,clips.map(f=>"file '"+f.replaceAll("'","'\\''")+"'").join('\n'));const filename='video_'+id+'.mp4',out=path.join(dir,filename);await command(ffmpeg,['-y','-f','concat','-safe','0','-i',list,'-c','copy','-movflags','+faststart',out]);const url='/videos/'+filename;db.prepare("INSERT INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,sort_order,created_at,finished_at,video_url) VALUES(?,?,?,'video','completed',100,?,?,0,0,3,0,datetime('now'),datetime('now'),?)").run(id,'Giữ nguyên ảnh gốc · ghép cảnh, không tạo sinh · không âm thanh',JSON.stringify(refTags),Number(duration),ratio,url);db.prepare('INSERT OR REPLACE INTO job_context(job_id,payload) VALUES (?,?)').run(id,JSON.stringify({prompt:'',ratio,duration:Number(duration),mode:'exact',references:refTags.map(tag=>{const r=db.prepare('SELECT filename FROM ref_images WHERE tag=?').get(tag);return {tag,url:'/uploads/'+r.filename}})}));res.json({jobs:[db.prepare('SELECT * FROM jobs WHERE id=?').get(id)],local:true})}catch(e){res.status(400).json({error:e.message})}finally{if(temp)fs.rmSync(temp,{recursive:true,force:true});busy=false}});module.exports=router;
